# The reference for crc64 (pure Python, table-driven): CRC-64/XZ (the
# reflected polynomial 0xC96C5795D7870F42, initial value and final xor all
# ones) of 8 MiB of generated bytes (byte i: (i * 2654435761 >> 13) & 255).
# The implementation is first checked against the catalogue's check value:
# "123456789" gives 0x995DC9BBDF1939FA. Prints the CRC in hexadecimal.
M = (1 << 64) - 1
POLY = 0xC96C5795D7870F42
TABLE = []
for b in range(256):
    c = b
    for _ in range(8):
        c = c >> 1 ^ POLY if c & 1 else c >> 1
    TABLE.append(c)


def crc64(data):
    c = M
    for b in data:
        c = TABLE[(c ^ b) & 255] ^ c >> 8
    return c ^ M


assert crc64(b"123456789") == 0x995DC9BBDF1939FA
data = bytes(((i * 2654435761) >> 13) & 255 for i in range(1 << 23))
print(f"{crc64(data):016x}")
